 for(const [id,key] of [['standalone-title','StandaloneTitle'],['standalone-help','StandaloneHelp'],['standalone-remember-label','StandaloneRemember'],['standalone-forget','StandaloneForget'],['standalone-directory','StandaloneChoose'],['standalone-compatible','StandaloneCompatible'],['standalone-open','StandaloneOpen'],['standalone-license-label','StandaloneLicenses'],['standalone-refresh','StandaloneRefresh'],['standalone-lock','StandaloneLock']])$(id).textContent=label(key);
 $('standalone-directory').disabled=typeof window.showDirectoryPicker!=='function';if(!window.crypto?.subtle||typeof Worker==='undefined'||typeof WebAssembly==='undefined'){status('StandaloneUnsupported');$('standalone-directory').disabled=$('standalone-compatible').disabled=true;}else status('StandaloneChooseHelp');
